const recoverReportedSubmission = `-- name: RecoverReportedSubmission :exec
WITH expired AS (
    UPDATE internal_mail_recipients r SET status='uncertain',code='submission_lease_expired',lease_id=NULL,lease_until=NULL,updated_at=now()
    WHERE r.namespace=$1 AND r.id=$2 AND r.status='submitting' AND r.lease_until<now() RETURNING r.id, r.namespace, r.message_id, r.address, r.status, r.attempts, r.lease_id, r.lease_until, r.next_attempt_at, r.code, r.updated_at, r.signing_selector, r.suppression_revision, r.recovery_id
)
INSERT INTO internal_mail_events(id,namespace,recipient_id,kind,code)
SELECT 'uncertain:'||id::text||':'||attempts::text,namespace,id,'uncertain',code FROM expired ON CONFLICT DO NOTHING
`

type RecoverReportedSubmissionParams struct {
	Namespace string
	ID        pgtype.UUID
}

func (q *Queries) RecoverReportedSubmission(ctx context.Context, db DBTX, arg RecoverReportedSubmissionParams) error {
	_, err := db.Exec(ctx, recoverReportedSubmission, arg.Namespace, arg.ID)
	return err
}

